import sys


LOW, HIGH = 18.5, 23.9


def classify(weight, height):
    """BMI 落在 [LOW, HIGH] 输出 Normal，否则 Abnormal。

    写成乘法而非除法：18.5 <= w/h^2 <= 23.9 等价于 18.5*h^2 <= w <= 23.9*h^2，
    少一次除法舍入，边界（恰好 18.5 / 23.9）更不容易被浮点误判。
    """
    if height <= 0:
        return "Abnormal"
    if LOW * height * height <= weight <= HIGH * height * height:
        return "Normal"
    return "Abnormal"


def solve(text):
    out = []
    for line in text.splitlines():
        parts = line.split()
        if len(parts) < 2:
            continue
        weight, height = float(parts[0]), float(parts[1])
        out.append(classify(weight, height))
    return out


def main():
    text = sys.stdin.read()
    for verdict in solve(text):
        sys.stdout.write(verdict + "\n")


if __name__ == "__main__":
    main()
